// Shape of src/transit/rapidRail.json (generated by scripts/build-transit-data.mjs).

export type ServiceKey = 'MonFri' | 'Sat' | 'Sun'

/** Seconds since service-day midnight; may exceed 86400 (after midnight). `to` is exclusive. */
export type Period = { from: number; to: number; headwayS: number }

/** Periods sorted by `from`. */
export type ServiceSchedule = { periods: Period[] }

export type Direction = {
  dir: 0 | 1
  /** Terminus name, e.g. "Gombak". */
  headsign: string
  /** [lng, lat] */
  shape: [number, number][]
  /** In travel order; offsetS is seconds from the first stop of this direction. */
  stops: { stationId: string; offsetS: number }[]
  service: Record<ServiceKey, ServiceSchedule>
}

export type Line = {
  id: string
  shortName: string
  name: string
  /** '#RRGGBB' */
  colour: string
  directions: Direction[]
}

export type Station = {
  id: string
  name: string
  lng: number
  lat: number
  lineIds: string[]
  stopIds: string[]
}

export type TransitData = { lines: Line[]; stations: Station[] }
